select case when unit_price >= 360 then 'high' when unit_price >= 200 then 'mid' else 'low' end as unit_price_bucket, product_id, round(avg(quantity), 2) as avg_quantity, max(quantity) - min(quantity) as quantity_range from order_items where product_id = 20 group by case when unit_price >= 360 then 'high' when unit_price >= 200 then 'mid' else 'low' end, product_id having quantity_range >= 45;
